std::string markdown_to_html(std::string& markdown_text) {
    // Replace markdown headers with HTML headers
    markdown_text = std::regex_replace(markdown_text, std::regex("#+ (.+)"), "<h1>$1</h1>");

    // Replace markdown bold text with HTML bold text
    markdown_text = std::regex_replace(markdown_text, std::regex("\\*\\*(.+?)\\*\\*"), "<b>$1</b>");

